#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSteamLogin: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SteamLogin

    public static func lift(_ handle: UInt64) throws -> SteamLogin {
        return SteamLogin(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SteamLogin) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SteamLogin {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SteamLogin, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSteamLogin_lift(_ handle: UInt64) throws -> SteamLogin {
    return try FfiConverterTypeSteamLogin.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSteamLogin_lower(_ value: SteamLogin) -> UInt64 {
    return FfiConverterTypeSteamLogin.lower(value)
}






public protocol SteamSessionProtocol: AnyObject, Sendable {
    
    /**
     * The share of each of `app_ids`' achievements the account unlocked, by
     * app ID, as `achievements` reads them: none for a game without
     * achievements or that Steam did not answer for. It fails only when no
     * game could be told.
     */
    func achievementShares(appIds: [UInt32], language: String) async throws  -> [UInt32: Double]
    
    /**
     * The game's achievements in `language`, such as the game page's: the
     * library's while the game was not played since they were read, unless
     * `fresh`, else Steam's, which the library then keeps.
     */
    func achievements(appId: UInt32, language: String, fresh: Bool) async throws  -> [LibraryAchievement]
    
    /**
     * When the account got each game its licenses grant, in seconds since
     * the Unix epoch, by app ID. It expands every license through PICS.
     */
    func acquisitions() async throws  -> [UInt32: UInt64]
    
    func cloudAutocloudMetadata() async throws  -> String
    
    /**
     * Explicit diagnostic operation using this already-authenticated session.
     * It downloads a verified backup; no Cloud mutation or game launch occurs.
     */
    func cloudBackup(appId: UInt32, directory: String) async throws  -> String
    
    func cloudInterruptionProbe(appId: UInt32, directory: String) async throws  -> String
    
    /**
     * Returns only Cloud preferences and source revision, never roaming data.
     */
    func cloudPreferences(appId: UInt32) async throws  -> String
    
    func cloudSdkCandidates() async throws  -> String
    
    func cloudTransferProbe(appId: UInt32, directory: String) async throws  -> String
    
    func details(appId: UInt32, language: String) async throws  -> SteamGameDetails
    
    func games() async throws  -> [SteamGame]
    
    /**
     * The session's state after `after_revision`: its friends and how it
     * stands with Steam, across its CM connections. No content-query mutex
     * is held.
     */
    func nextFriends(afterRevision: UInt64) async  -> SteamFriendsSnapshot
    
    /**
     * Declared application platforms in batches; an empty platform list means
     * unknown. Each game's library artwork comes with them, in `language`.
     */
    func platforms(appIds: [UInt32], language: String) async throws  -> [SteamGamePlatforms]
    
    func profile() async throws  -> SteamProfile
    
    /**
     * Replaces the CM connection, live or not, and connects again, as on the
     * player's retry or the Mac's wake. Nothing once Steam asked the account
     * to sign in again.
     */
    func reconnect() 
    
    /**
     * Stops reconnecting and ends the CM connection. Also wakes UniFFI
     * futures, whose Swift wrappers do not cancel Rust awaits.
     */
    func shutdown() 
    
    /**
     * Cookies that sign Steam's sites in as this session's account.
     */
    func webCookies() async throws  -> [SteamWebCookie]
    
    /**
     * Marks the conversation read up to `timestamp` in every session.
     */
    func ack(friendSteamId: UInt64, timestamp: UInt32) async throws 
    
    func activeSessions() async throws  -> [SteamChatSession]
    
    /**
     * Invites into `invite`, which the account's running game of `app_id`
     * reported itself. Fails with `backend.steam.invite.unavailable` for an
     * invitation Steam cannot carry or while the account plays another game.
     */
    func inviteIntoGame(friendSteamId: UInt64, appId: UInt32, invite: SteamGameInvite) async throws 
    
    /**
     * Fails with `backend.steam.invite.unavailable` unless the account plays
     * `app_id` and that game can take an invitation now.
     */
    func inviteToGame(friendSteamId: UInt64, appId: UInt32) async throws 
    
    /**
     * Suspends until chat events follow `after_sequence` or the session ends.
     */
    func nextChat(afterSequence: UInt64) async  -> SteamChatEvents
    
    /**
     * Suspends until the invitations friends sent change or the session ends.
     */
    func nextInvites(afterRevision: UInt64) async  -> SteamReceivedInvites
    
    /**
     * Suspends until the own game's revision differs or the session ends.
     */
    func nextOwnGame(afterRevision: UInt64) async  -> SteamOwnGame
    
    /**
     * Up to `count` (at most 50) messages before `before`, or the latest ones.
     */
    func recentMessages(friendSteamId: UInt64, before: SteamChatPosition?, count: UInt32) async throws  -> SteamChatHistory
    
    func sendMessage(friendSteamId: UInt64, text: String) async throws  -> SteamSentMessage
    
    /**
     * Throttled per friend in Rust; calling on every keystroke is fine.
     */
    func sendTyping(friendSteamId: UInt64) async throws 
    
    /**
     * Shows the account Online again, for instance after a game ended.
     */
    func setOnline() async throws 
    
}
